SELECT SUM(Total_Horses) AS Total_Horses
FROM farm
ORDER BY Total_Horses ASC;

SELECT COUNT(DISTINCT date) 
FROM weather 
WHERE mean_humidity > 50 AND mean_visibility_miles > 8;

SELECT COUNT(DISTINCT date) 
FROM weather 
WHERE mean_humidity > 50 AND mean_visibility_miles > 8;

SELECT DISTINCT Publisher 
FROM publication 
WHERE Price > 10000000 OR Price < 5000000;

SELECT AVG(price) 
FROM flight 
WHERE origin = 'LA' AND destination = 'Honolulu';

SELECT AllergyType FROM Allergy_Type WHERE Allergy IN (
    SELECT Allergy FROM Has_Allergy GROUP BY Allergy ORDER BY COUNT(*) DESC LIMIT 1
)

SELECT AllergyType FROM Allergy_Type WHERE Allergy IN (
    SELECT Allergy FROM Has_Allergy GROUP BY Allergy ORDER BY COUNT(*) ASC LIMIT 1
)

SELECT billing_state, COUNT(*) AS invoice_count
FROM invoices
GROUP BY billing_state;

SELECT COUNT(id) AS number_of_invoices, SUM(total) AS invoice_total
FROM invoices
WHERE billing_state = 'CA';

SELECT COUNT(id) AS number_of_invoices, SUM(total) AS total_money_billed
FROM invoices
WHERE billing_state = 'CA';

SELECT Accounts.account_id, Accounts.customer_id, CONCAT(Customers.customer_first_name, ' ', Customers.customer_last_name) AS customer_name
FROM Accounts
JOIN Customers ON Accounts.customer_id = Customers.customer_id;

SELECT Address FROM shop WHERE Shop_ID NOT IN (
    SELECT Shop_ID FROM happy_hour_member WHERE Member_ID IN (
        SELECT Member_ID FROM member WHERE Membership_card = 'Black'
    )
)

SELECT Model_name FROM chip_model WHERE Model_name NOT IN (
    SELECT T2.chip_model FROM phone AS T1 INNER JOIN chip_model AS T2 ON T1.chip_model = T2.Model_name WHERE T1.Accreditation_type = 'Full'
)

SELECT Player, SUM(Years_Played) AS Total_Years_Played
FROM player
GROUP BY Player;

SELECT g.guest_first_name, ab.booking_start_date, ab.booking_end_date
