SELECT name FROM instructor WHERE ID NOT IN (
    SELECT DISTINCT T2.ID FROM teaches AS T1 INNER JOIN section AS T2 ON T1.sec_id = T2.sec_id AND T1.course_id = T2.course_id WHERE T2.semester = 'Spring'
)

