SELECT DISTINCT T1.Position FROM player AS T1 INNER JOIN competition_result AS T2 ON T1.Club_ID = T2.Club_ID_1 WHERE T1.Points > 20 AND T1.Points < 10
UNION
SELECT DISTINCT T1.Position FROM player AS T1 INNER JOIN competition_result AS T2 ON T1.Club_ID = T2.Club_ID_2 WHERE T1.Points > 20 AND T1.Points < 10;

SELECT AVG(SALARY) AS AverageSalary
FROM employees
